#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // Expect at least program name, number of vertices, number of edges
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 1;
    }

    int n = atoi(argv[1]); // number of vertices
    int m = atoi(argv[2]); // number of edges

    // Constraints observed in the original binary (max 8 vertices, max 8 edges)
    if (n <= 0 || n > 8 || m < 0 || m > 8) {
        puts("INVALID_INPUT");
        return 1;
    }

    // Verify that the correct number of arguments is supplied
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    int indeg[8] = {0};
    int adj[8][8] = {{0}}; // adjacency matrix, 0/1 entries

    // Read edges
    for (int i = 0; i < m; ++i) {
        int u = atoi(argv[3 + 2 * i]);
        int v = atoi(argv[3 + 2 * i + 1]);
        // Validate vertex indices
        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        // Record edge if not already present (avoid double counting indegree)
        if (!adj[u][v]) {
            adj[u][v] = 1;
            indeg[v]++;
        }
    }

    // Kahn's algorithm for topological sorting (using a simple queue)
    int queue[8];
    int qhead = 0, qtail = 0;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) {
            queue[qtail++] = i;
        }
    }

    int order[8];
    int processed = 0;
    while (qhead < qtail) {
        int u = queue[qhead++];
        order[processed++] = u;
        for (int v = 0; v < n; ++v) {
            if (adj[u][v]) {
                adj[u][v] = 0;
                if (--indeg[v] == 0) {
                    queue[qtail++] = v;
                }
            }
        }
    }

    // If we couldn't process all vertices, there is a cycle
    if (processed != n) {
        puts("CYCLE");
        return 1;
    }

    // Output the topological order, space‑separated, followed by a newline
    for (int i = 0; i < processed; ++i) {
        if (i) putchar(' ');
        printf("%d", order[i]);
    }
    putchar('\n');
    return 0;
}
}
